// Des: Tests for label registry parse and bilingual matching
// Flo: embedded registry + hand nodes > assert finds
// I/O: nodes > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const lab = @import("cf-labl-load.zig"); const fnd = @import("ru-labl-find.zig"); const snap = @import("ru-page-snap.zig"); const T = std.testing;
fn nd(role: []const u8, name: []const u8, bid: i64) snap.Node { return .{ .role = role, .name = name, .valu = "", .bid = bid }; }
test "built-in registry parses and every job key exists" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const reg = try lab.builtin(aren.allocator()); try T.expect(reg.keys.map.count() > 50); try T.expect(lab.missing(&reg) == null); try T.expectEqualStrings("textbox", reg.get("sear_boxz").?.role); try T.expect(reg.jobKeys("send") != null); try T.expect(reg.get("nope") == null); }
test "bad json and missing file are BadConfig, missing job key is reported" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); try T.expectError(error.BadConfig, lab.parse(aren.allocator(), "{bad")); try T.expectError(error.BadConfig, lab.load(aren.allocator(), T.io, "no-such-labels-za.json")); const reg = try lab.parse(aren.allocator(), "{\"keys\":{\"a\":{\"role\":\"button\"}},\"jobs\":{\"j\":{\"rest\":[\"zz\"]}}}"); try T.expectEqualStrings("zz", lab.missing(&reg).?); }
test "names joins vi then en" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const reg = try lab.builtin(aren.allocator()); const ns = try reg.names(aren.allocator(), "send_butt"); try T.expectEqualStrings("Gửi", ns[0]); try T.expectEqualStrings("Send", ns[ns.len - 1]); try T.expectError(error.NoElem, reg.names(aren.allocator(), "zzz")); }
test "finds a Vietnamese and an English button by the same key" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const reg = try lab.builtin(aren.allocator()); const vi = [_]snap.Node{ nd("button", "Gửi", 1), nd("textbox", "Tìm kiếm", 2) }; const en = [_]snap.Node{ nd("button", "Send", 3), nd("textbox", "Search", 4) }; try T.expectEqual(@as(i64, 1), fnd.findKey(&reg, &vi, "send_butt").?.bid); try T.expectEqual(@as(i64, 3), fnd.findKey(&reg, &en, "send_butt").?.bid); try T.expectEqual(@as(i64, 4), fnd.findKey(&reg, &en, "sear_boxz").?.bid); try T.expect(fnd.findKey(&reg, &vi, "nope") == null); }
test "role must match, exact beats substring, alternate drift name works" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const reg = try lab.builtin(aren.allocator()); const ns = [_]snap.Node{ nd("button", "Tạo nhóm", 1), nd("textbox", "Tạo", 2), nd("button", "Tạo", 3) }; try T.expectEqual(@as(i64, 3), fnd.findKey(&reg, &ns, "crea_butt").?.bid); const alt = [_]snap.Node{nd("button", "Gửi tin nhắn", 9)}; try T.expectEqual(@as(i64, 9), fnd.findKey(&reg, &alt, "send_butt").?.bid); const wrong = [_]snap.Node{nd("link", "Gửi", 5)}; try T.expect(fnd.findKey(&reg, &wrong, "send_butt") == null); }
test "findWith needs the label and the extra text" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const reg = try lab.builtin(aren.allocator()); const ns = [_]snap.Node{ nd("button", "Đồng ý Lan", 1), nd("button", "Đồng ý Minh", 2), nd("button", "Bỏ qua Minh", 3) }; try T.expectEqual(@as(i64, 2), fnd.findWith(&reg, &ns, "acce_butt", "Minh").?.bid); try T.expect(fnd.findWith(&reg, &ns, "acce_butt", "Zed") == null); }
test "allKey and role-only keys" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const reg = try lab.builtin(aren.allocator()); const ns = [_]snap.Node{ nd("listitem", "Mom", 1), nd("listitem", "Boss", 2), nd("button", "Gửi", 3) }; const all = try fnd.allKey(aren.allocator(), &reg, &ns, "chat_item"); try T.expectEqual(@as(usize, 2), all.len); try T.expectEqual(@as(usize, 0), (try fnd.allKey(aren.allocator(), &reg, &ns, "zzz")).len); try T.expect(fnd.present(&reg, &ns, "chat_item")); try T.expect(!fnd.present(&reg, &ns, "mesg_item")); }
test "marks and self prefix in both languages" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const reg = try lab.builtin(aren.allocator()); try T.expectEqual(@as(?usize, 4), fnd.markPos(&reg, "Mom unread 2", "unre_mark")); try T.expectEqual(@as(?usize, 3), fnd.markPos(&reg, "Me chưa đọc", "unre_mark")); try T.expect(fnd.markPos(&reg, "Boss", "unre_mark") == null); try T.expectEqual(@as(?usize, 4), fnd.selfPrefix(&reg, "me: hi")); try T.expectEqual(@as(?usize, 7), fnd.selfPrefix(&reg, "Bạn: ok")); try T.expect(fnd.selfPrefix(&reg, "hello") == null); }
